import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const sourceDir = join(root, 'src', 'assets', 'og');
const outFile = join(root, 'src', 'og', 'ogAssetData.ts');

const files = readdirSync(sourceDir).filter((name) => /\.(woff|png)$/.test(name)).sort();
const entries = files.map((name) => `    '${name}': '${readFileSync(join(sourceDir, name)).toString('base64')}',`);

writeFileSync(
    outFile,
    [
        '// Generated by scripts/generate-og-assets.mjs from src/assets/og. Do not edit by hand.',
        'export const OG_ASSET_DATA: Record<string, string> = {',
        ...entries,
        '};',
        '',
    ].join('\n'),
);

console.log(`Wrote ${files.length} assets to ${outFile}`);
